import {FIGSHARE_META,CORPUS_SAMPLES} from './samples.mjs';
import {comparisonMetrics,validateAdjudication} from './comparison.mjs';
import {escapeHTML,fixedDate,shortTime,toInput,fromInput,ageLabel,markdownReport} from './export.mjs';
import {makeGraph} from './graph.mjs';
import {GraphPanel} from './graph-panel.mjs';
import {graphBuildMode} from './graph-runtime.mjs';
const $=s=>document.querySelector(s);
const h=escapeHTML;
const newId=()=>{if(globalThis.crypto?.randomUUID)return crypto.randomUUID();const a=new Uint32Array(4);crypto.getRandomValues(a);return [...a].map(x=>x.toString(16).padStart(8,'0')).join('-');};
const TASKS={all:'Todas las afirmaciones',devices:'Dispositivos',symptoms:'Síntomas',plans:'Planes y acciones'};
const STAGES={'handover-record':{from:'handover',to:'record',label:'Entrega → registro',symbol:'H → R'},'reference-handover':{from:'reference',to:'handover',label:'Referencia → entrega',symbol:'P → H'}};
const STATUS={unassessed:'Sin evaluar',preserved:'Conservada',omitted:'Omitida',contradicted:'Contradicha',altered:'Alterada · modalidad',indeterminate:'Indeterminada'};
const UNC={not_assessed:'Sin evaluar',preserved:'Conservada',lost:'Eliminada',not_applicable:'No aplica'};
const state={bundle:demoBundle(),tab:'graph',mobile:'graph',selected:'A06@1',source:'R04',context:{actor:'Enfermería · entrega',task:'devices',clinicalAt:demoTime('20:05'),kappa:demoTime('20:05'),includeHistory:false},graph:{positions:new Map(),viewport:null},graphView:{},search:'',dirty:false,compareDirty:false,showInspector:false,graphDrawer:'closed',corpus:[],corpusName:'',labCopies:5,labStep:4,labLate:true,labNew:false};
const cmp={schema:'traza-comparison/0.1',synthetic:true,task:'Continuidad del dispositivo A al cierre de la entrega',reference:'',handover:'',record:'',rows:[],complete:false,stage:'handover-record'};
let currentView,graphPanel=null,toastTimer;
function icon(name){const paths={graph:'<circle cx="5" cy="6" r="2.5"/><circle cx="18" cy="5" r="2.5"/><circle cx="16" cy="18" r="2.5"/><path d="m7.4 5.8 8.1-.6M6.6 8l7.8 8M17.6 7.5l-1.2 8"/>',doc:'<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/>',table:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M3 14h18M9 4v16"/>',compare:'<rect x="3" y="3" width="6" height="18" rx="1"/><rect x="15" y="3" width="6" height="18" rx="1"/><path d="M10 9h4m-2-2 2 2-2 2M14 16h-4m2-2-2 2 2 2"/>',lab:'<path d="M9 3h6m-5 0v7l-5 9c-.6 1 .1 2 1 2h12c1 0 1.6-1 1-2l-5-9V3M8 15h8"/>',folder:'<path d="M3 6h6l2 2h10v12H3zM3 6V4h6l2 2h8v2"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',up:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevron:'<path d="m9 5 7 7-7 7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',edit:'<path d="m4 16 11-11 4 4L8 20H4zM13 7l4 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',link:'<path d="m9 15 6-6M8 16l-2 2a4 4 0 0 1-5-5l4-4a4 4 0 0 1 5 0M16 8l2-2a4 4 0 0 0-5-5l-4 4" transform="translate(2 2) scale(.9)"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6zM8 12l3 3 5-6"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.doc}</svg>`;}
function options(map,val){return Object.entries(map).map(([k,v])=>`<option value="${h(k)}" ${k===val?'selected':''}>${h(v)}</option>`).join('');}
function btn(action,label,ico='',cls='',extra=''){return `<button type="button" data-action="${action}" class="${cls}" ${extra}>${ico?icon(ico):''}${label}</button>`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function disposeGraph(){graphPanel?.destroy();graphPanel=null;}
function resetGraph(){disposeGraph();state.graph={positions:new Map(),viewport:null};state.graphView={};state.graphDrawer='closed';}
function adopt(bundle,{archive=false}={}){const v=validateBundle(bundle);if(!v.ok)throw Error(v.errors.join('\n'));state.bundle=bundle;state.context.task=archive?'all':'devices';state.context.kappa=archive?null:demoTime('20:05');state.context.clinicalAt=archive?null:demoTime('20:05');state.context.includeHistory=false;state.selected=null;state.source=null;state.tab='graph';state.mobile='graph';state.dirty=false;resetGraph();render();}
function showGraphDrawer(which){state.graphDrawer=which;const w=$('.traza-graph-workspace');if(w){w.dataset.drawer=which;const target=which==='source'?w.querySelector('.source-text'):which==='detail'?w.querySelector('.inspector-body'):null;if(target)requestAnimationFrame(()=>{target.scrollTop=0;if(which==='source')target.querySelector('mark')?.scrollIntoView({block:'nearest'});});}}
function canReplace(){return !state.dirty||window.confirm('Hay anotaciones sin exportar. ¿Descartar esos cambios y abrir otro caso?');}
function getSelected(){return currentView.claims.find(c=>keyOf(c)===state.selected)||currentView.roots.find(r=>'root:'+r.id===state.selected)||null;}
function selectNode(id){
  const claim=currentView.claims.find(c=>keyOf(c)===id),root=currentView.roots.find(r=>'root:'+r.id===id),doc=currentView.documents.find(d=>'doc:'+d.id===id);
  if(!claim&&!root&&!doc)return;
  state.selected=id;state.source=(claim||root)?.source.documentId||doc.id;
  if(state.tab!=='graph'||!$('.workspace')){render();return;}
  const source=$('.source-panel');if(source)source.outerHTML=sourceHTML();
  const body=$('.inspector-body');if(body)body.innerHTML=inspectorHTML();
  const label=$('.inspector .panel-head .mono');if(label)label.textContent=id;
  $('.workspace').dataset.mobile=state.mobile;graphPanel?.setSelection(id);
  requestAnimationFrame(()=>$('.source-text mark')?.scrollIntoView({block:'center',inline:'nearest'}));
}
function render(){
  disposeGraph();
  currentView=selectView(state.bundle,state.context);
  if(!currentView.claims.some(c=>keyOf(c)===state.selected)&&!currentView.roots.some(r=>'root:'+r.id===state.selected)&&!currentView.documents.some(d=>'doc:'+d.id===state.selected))state.selected=currentView.claims.length?keyOf(currentView.claims[0]):null;
  if(!currentView.documents.some(d=>d.id===state.source))state.source=getSelected()?.source.documentId||currentView.documents[0]?.id||null;
  const count=currentView.claims.length;
  $('#app').innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><div class="brand-mark">${icon('graph')}</div><div><h1>TRAZA <span>clínica</span></h1><small>DEL TEXTO A SU EVIDENCIA</small></div></div><div class="top-actions"><span class="privacy"><i class="status-dot"></i> ${graphBuildMode()==='offline'?'Grafo sin red · motor local':'Motor externo'}</span>${btn('corpus','<span class="button-label">Corpus</span>','folder')}${btn('import','<span class="button-label">Importar</span>','up','', 'aria-label="Importar expediente JSON"')}${btn('export','<span class="button-label">Exportar</span>','down','primary','aria-label="Exportar expediente y vista"')}${btn('about','','info','plain','aria-label="Acerca de la teoría y los límites"')}</div></header><section class="workhead"><div class="case-line"><div><h2>${h(state.tab==='compare'?'Comparación documental · matriz independiente':state.tab==='lab'?'Laboratorio matemático · escenarios artificiales':state.bundle.case.title)}</h2><p>${state.tab==='compare'?'Fuentes y adjudicaciones propias · no se atribuyen al corpus seleccionado':state.tab==='lab'?'Experimentos aislados · no representan probabilidades del paciente':state.bundle.corpus?'Diálogo sintético · fuente externa · sin etiquetas de consenso':'Expediente sintético · representación documental'} · ${state.tab==='compare'?'sin filtro temporal automático':state.tab==='lab'?'parámetros didácticos':state.context.kappa?'vista con corte temporal':'archivo sin corte temporal'}</p></div><div class="case-tools">${btn('demo','Demo','','plain')}${btn('new-source','<span class="add-source-label">Añadir texto</span>','plus','','aria-label="Añadir texto sintético"')}</div></div><nav class="tabs" aria-label="Vistas del laboratorio">${[['graph','Grafo','graph'],['table','Afirmaciones','table'],['compare','Comparar','compare'],['lab','Laboratorio','lab']].map(([id,label,ic])=>btn('tab',`${label}${id==='table'?` <span class="count">${count}</span>`:''}`,ic,state.tab===id?'active':'',`data-tab="${id}" aria-current="${state.tab===id?'page':'false'}"`)).join('')}</nav></section>${['graph','table'].includes(state.tab)?contextHTML():''}<main class="main" id="main">${state.tab==='graph'?workspaceHTML():state.tab==='table'?tableHTML():state.tab==='compare'?comparisonHTML():labHTML()}</main><footer class="footer"><span><strong>Prototipo de investigación</strong> · Sólo datos sintéticos. No usar para decisiones asistenciales.</span><span class="footer-technical">v0.3.0 · Grafo local · ${state.dirty||state.compareDirty?'Cambios sin exportar':'Sesión en memoria'} · ${h(state.tab==='compare'?'Matriz P/H/R':state.tab==='lab'?'Modelo binario artificial':state.bundle.case.id)}</span></footer></div>`;
  if(state.tab==='graph'){drawGraph();requestAnimationFrame(()=>{const marked=$('.source-text mark');if(marked)marked.scrollIntoView({block:'center',inline:'nearest'});});}
}
function contextHTML(){return `<section class="context" aria-label="Contexto de lectura"><label>Actor declarado<select id="actor">${options({'Enfermería · entrega':'Enfermería · entrega','Investigación documental':'Investigación documental','Revisión interdisciplinaria':'Revisión interdisciplinaria'},state.context.actor)}</select></label><label>Tarea / filtro<select id="task">${options(TASKS,state.context.task)}</select></label><label>t · tiempo de interés, UTC−03<input id="clinical-at" type="datetime-local" value="${toInput(state.context.clinicalAt)}" aria-label="Tiempo clínico t"></label><label>κ · disponible hasta, UTC−03<input id="cutoff" type="datetime-local" value="${toInput(state.context.kappa)}" ${state.context.kappa===null?'disabled':''} aria-label="Corte de disponibilidad kappa"></label><label class="check context-check"><input id="archive" type="checkbox" ${state.context.kappa===null?'checked':''}>Archivo sin corte κ</label>${!state.bundle.corpus?`<div class="time-presets"><small>RECORRER EL CASO · t = κ</small>${['12:30','13:05','20:05'].map(t=>btn('time',t,'',state.context.kappa===demoTime(t)?'active':'',`data-time="${t}"`)).join('')}</div>`:''}</section>`;}
function workspaceHTML(){return `<div class="workspace traza-graph-workspace" data-drawer="${state.graphDrawer}" data-mobile="${state.mobile}">${sourceHTML()}<section class="panel canvas-panel"><div class="panel-head">${icon('graph')}<h3>Red de evidencia</h3><span class="graph-status">${currentView.claims.length} afirmaciones · ${currentView.roots.length} raíces</span>${btn('detail','','info','plain show-detail-btn','style="display:none" aria-label="Ver inspector"')}</div><div class="canvas" id="canvas"></div></section><aside class="panel inspector"><div class="panel-head">${icon('info')}<h3>Detalle documental</h3><span class="mono">${h(state.selected||'—')}</span>${btn('graph-close','×','','gv-drawer-close','aria-label="Cerrar panel"')}</div><div class="inspector-body">${inspectorHTML()}</div></aside></div>`;}
function sourceHTML(){const d=currentView.documents.find(d=>d.id===state.source),s=getSelected(),source=s?.source?.documentId===d?.id?s.source:null;let text=d?h(d.text):'';if(source)text=h(d.text.slice(0,source.start))+`<mark>${h(source.quote)}</mark>`+h(d.text.slice(source.end));return `<aside class="panel source-panel"><div class="panel-head">${icon('doc')}<h3>Texto fuente</h3><span class="mono">${d?h(d.id):'—'}</span>${btn('graph-close','×','','gv-drawer-close','aria-label="Cerrar panel"')}</div>${d?`<div class="source-picker"><select id="source-select" aria-label="Documento fuente">${currentView.documents.map(x=>`<option value="${h(x.id)}" ${x.id===d.id?'selected':''}>${h(x.id+' · '+x.title)}</option>`).join('')}</select><div class="source-meta"><span>Documentado ${h(shortTime(d.authoredAt))}</span><span>Disponible ${h(shortTime(d.availableAt))}</span></div></div><div class="source-text" tabindex="0" aria-label="Fuente textual sin modificar">${text}</div><div class="source-note">${source?`Cita exacta · UTF-16 [${source.start}, ${source.end}). `:''}Texto original conservado. Seleccionar un nodo revela su fragmento.</div>`:`<div class="empty"><h3>Sin fuente disponible</h3><p>No hay documentos fechados antes de este corte. Los tiempos desconocidos no se suponen actuales.</p></div>`}</aside>`;}
function inspectorHTML(){const d=!getSelected()&&currentView.documents.find(d=>'doc:'+d.id===state.selected);if(d)return `<span class="type-tag">Fuente textual · no observación</span><h2 class="inspect-title">${h(d.title)}</h2><p>Este nodo es un documento. No acredita una observación ni una raíz independiente.</p><dl class="detail-grid"><dt>ID</dt><dd>${h(d.id)}</dd><dt>Autoría</dt><dd>${h(fixedDate(d.authoredAt))}</dd><dt>Disponibilidad</dt><dd>${h(fixedDate(d.availableAt))}</dd></dl><p>El texto íntegro permanece en el panel de fuente.</p>`;const c=getSelected();if(!c)return '<div class="empty"><h3>Una afirmación, su contexto</h3><p>Selecciona un nodo o carga un texto sintético.</p></div>';const root=state.selected.startsWith('root:');const roots=root?[c]:currentView.roots.filter(r=>c.rootIds.includes(r.id));const details=[['Sujeto',c.subject||'No resuelto'],['Entidad',c.entity||'No resuelta'],['Episodio',c.episode||'No resuelto'],['Atributo',c.concept||'Sin estructurar'],['Polaridad',POLARITIES[c.polarity]],['Unidad',c.unit||'No declarada']];const cues=!root?uncertaintyCues(c.source.quote):[];return `<span class="type-tag ${!root&&c.review==='pending'?'amber':''}">${root?'Evidencia de origen declarada':c.review==='pending'?'Propuesta · sin revisar':MODALITIES[c.modality]}</span><h2 class="inspect-title">${h(root?c.id:c.entity&&c.value?`${c.entity} · ${c.value}`:c.speaker||MODALITIES[c.modality])}</h2><blockquote class="quote">${h(c.source.quote)}</blockquote><dl class="detail-grid">${details.map(([a,b])=>`<dt>${a}</dt><dd>${h(b)}</dd>`).join('')}${c.speaker?`<dt>Interlocutor</dt><dd>${h(c.speaker)}</dd>`:''}</dl><section class="detail-section"><h4>Tiempos distintos</h4><dl class="detail-grid"><dt>${root?'Evidencia':'Afirmado · tᵢ'}</dt><dd>${h(fixedDate(root?c.evidenceAt:c.eventAt))}</dd>${!root?`<dt>Autoría · dᵢ</dt><dd>${h(fixedDate(c.authoredAt))}</dd>`:''}<dt>Disponible · κᵢ</dt><dd>${h(fixedDate(c.availableAt))}</dd></dl>${!root&&c.eventAt&&state.context.clinicalAt&&Date.parse(c.eventAt)>Date.parse(state.context.clinicalAt)?'<p class="alert-inline">Se refiere a un tiempo posterior a t. Se muestra porque ya estaba disponible; no afirma una ejecución.</p>':''}</section><section class="detail-section"><h4>Procedencia ${root?'':'· ρᵢ'}</h4>${roots.length?roots.map(r=>btn('select-root',`${h(r.id)} · ${h(shortTime(r.evidenceAt))}<span>${h(ageLabel(evidenceAge(r,state.context.kappa)))} al corte</span>`,'link','root-link',`data-root="${h(r.id)}"`)).join(''):'<p class="inspect-note">Sin raíz de evidencia declarada. Una mención en la conversación no se convierte automáticamente en una observación nueva.</p>'}<p class="inspect-note">${root?'El origen fue declarado; no acredita independencia ni verdad clínica.':'Una copia conserva su raíz y su tiempo. Raíces distintas no prueban independencia.'}</p></section>${!root?`<section class="detail-section"><h4>Incertidumbre y revisión</h4><p class="inspect-note">${h(c.uncertainty||'No anotada. Esto no demuestra ausencia de incertidumbre.')}</p>${cues.length?`<p class="alert-inline">${cues.length} indicadores léxicos: ${h(cues.map(x=>'«'+x.quote+'»').join(', '))}. Sólo candidatos de navegación; no anotaciones validadas.</p>`:''}<p class="inspect-note">${h(c.reviewNote)}</p><div class="inspector-actions">${btn('review','Revisar','edit','primary')}${btn('relation','Relacionar','link')}</div></section>`:''}`;}
function drawGraph(){const host=$('#canvas');if(!host)return;disposeGraph();graphPanel=new GraphPanel(host,{view:currentView,selected:state.selected,state:state.graphView,onSelect:selectNode,onOpenSource:()=>showGraphDrawer('source'),onOpenDetail:()=>showGraphDrawer('detail')});}
function tableHTML(){const needle=state.search.toLowerCase(),claims=currentView.claims.filter(c=>[keyOf(c),c.source.quote,c.subject,c.modality].join(' ').toLowerCase().includes(needle));return `<section class="scroll-page"><div class="page-heading"><div><h2>Afirmaciones trazables</h2><p>Cada fila conserva su fragmento original y sus tiempos. Revisada significa revisión de la representación, no verificación del estado del paciente.</p></div>${btn('export','Exportar vista','down')}</div><div class="table-tools"><input id="claim-search" type="search" placeholder="Buscar en ID, sujeto o texto…" value="${h(state.search)}" aria-label="Buscar afirmaciones"><label class="check"><input id="history" type="checkbox" ${state.context.includeHistory?'checked':''}>Mostrar versiones anteriores</label><span class="small">${claims.length} filas visibles</span></div><div class="table-wrap"><table><thead><tr><th>Versión</th><th>Fragmento / fuente</th><th>Modalidad</th><th>t afirmado</th><th>κ disponible</th><th>Procedencia</th><th>Revisión</th></tr></thead><tbody>${claims.map(c=>`<tr><td>${btn('table-node',h(keyOf(c)),'','','data-key="'+h(keyOf(c))+'"')}</td><td class="text-cell">${h(c.source.quote)}<div class="small">${h(c.source.documentId)} · [${c.source.start}, ${c.source.end}) · ${h(c.subject||'sujeto sin resolver')}</div></td><td>${h(MODALITIES[c.modality])}</td><td>${h(fixedDate(c.eventAt))}</td><td>${h(fixedDate(c.availableAt))}</td><td>${h(c.rootIds.join(', ')||'Sin raíz')}</td><td><span class="type-tag ${c.review==='pending'?'amber':''}">${c.review==='pending'?'Pendiente':'Revisada'}</span></td></tr>`).join('')||'<tr><td colspan="7">Sin filas para esta consulta.</td></tr>'}</tbody></table></div><p class="semantic-note">Los fragmentos sin clasificar no equivalen a hechos clínicos atómicos. t ayuda a revisar pertinencia temporal; κ limita la información disponible. Las fuentes con κ desconocido sólo aparecen en el modo archivo.</p></section>`;}
function labHTML(){const a=copyPosterior(state.labCopies),b=copyPosterior(state.labCopies,true),records=[{root:'O1',value:1,time:0,available:0}];if(state.labLate)records.push({root:'O2',value:0,time:1,available:4});if(state.labNew)records.push({root:'O3',value:1,time:4,available:4});const p=hmmPosterior(records,state.labStep,state.labStep);return `<section class="scroll-page"><div class="lab-layout"><div class="page-heading"><div><h2>Lo que cambia la evidencia</h2><p>Dos experimentos matemáticos aislados del expediente. No calculan probabilidades clínicas ni evalúan pacientes. Parámetros didácticos tomados del manuscrito, no aprendidos del corpus.</p></div></div><div class="info-banner">S<sub>t</sub> no es observado por esta aplicación. Estas probabilidades pertenecen a un modelo binario artificial, no a los nodos del grafo.</div><section class="lab-section"><div><h3>Repetir una nota<br>no repite la observación.</h3><p>Una copia mecánica conocida conserva una sola raíz. Una reevaluación puede aportar nueva evidencia, incluso con el mismo texto. La independencia condicional debe justificarse por separado.</p><div class="formula">P(X | R, copia(R)) = P(X | R)</div><p>Prior 0,5 · razón de verosimilitud 4 · hipótesis fija. Sólo el comparador supone observaciones independientes.</p></div><div class="lab-results"><label>Número de apariciones: <strong id="copy-count">${state.labCopies}</strong><input id="copy-range" type="range" min="1" max="8" step="1" value="${state.labCopies}"></label><div class="prob-row"><span>Una evidencia y sus copias</span><strong id="copy-correct">${a.toFixed(4)}</strong></div><div class="bar"><span id="copy-bar" style="width:${a*100}%"></span></div><div class="prob-row"><span>Comparador: independientes</span><strong id="copy-naive">${b.toFixed(6)}</strong></div><div class="bar alt"><span id="naive-bar" style="width:${b*100}%"></span></div><p class="small" style="margin-top:20px">El número de notas no determina el número de fuentes independientes.</p></div></section><section class="lab-section"><div><h3>Una llegada tardía<br>conserva su tiempo original.</h3><p>La observación positiva llega en el paso 0. La negativa corresponde al paso 1, pero sólo está disponible en el paso 4. Antes de ese corte no entra al cálculo.</p><div class="formula">b<sub>t|κ</sub> = P(X<sub>t</sub> = 1 | I<sub>κ</sub>)</div><p>T = [[0,9; 0,1], [0,1; 0,9]] · exactitud de emisión 0,8. Los pasos son abstractos, no horas. El filtro usa t = κ.</p></div><div class="lab-results"><label>Paso de consulta y corte κ<select id="hmm-step">${options({'0':'0 · primera observación','1':'1 · todavía no llega la negativa','2':'2 · sin nueva información','3':'3 · sin nueva información','4':'4 · llegada tardía','5':'5 · propagación'},String(state.labStep))}</select></label><label class="check"><input id="hmm-late" type="checkbox" ${state.labLate?'checked':''}>Incluir negativa de t=1, disponible desde κ=4</label><label class="check"><input id="hmm-new" type="checkbox" ${state.labNew?'checked':''}>Nueva positiva independiente en t=4, κ=4</label><small>Posterior del modelo artificial</small><strong class="lab-result-number">${p.toFixed(8)}</strong><p class="small" style="margin:10px 0 0">${state.labStep<4?'La evidencia con llegada en 4 queda excluida, aunque esté activada.':'La evidencia tardía se incorpora a t=1, no como medición de t=4.'}</p></div></section></div></section>`;}
function comparisonHTML(){const rows=cmp.rows.filter(r=>r.stage===cmp.stage),m=safeMetrics();return `<section class="scroll-page"><div class="page-heading"><div><h2>De lo comunicado a lo escrito</h2><p>Compara representaciones de un caso sintético. La referencia P no equivale al estado real S. Las unidades y sus equivalencias se adjudican manualmente; la aplicación no interpreta automáticamente la completitud clínica.</p></div>${btn('compare-demo','Ejemplo anotado','','')}</div><div class="representation-row"><p><strong>P</strong> Perfil de referencia sintético</p><p><strong>H</strong> Información comunicada</p><p><strong>R</strong> Registro resultante</p></div><label style="margin-bottom:17px">Tarea y alcance comparado<input id="cmp-task" value="${h(cmp.task)}" maxlength="500" placeholder="Sujeto, episodio, atributo, tiempo y tarea…"></label><div class="triple">${[['reference','P','Perfil de referencia · opcional'],['handover','H','Entrega comunicada'],['record','R','Registro resultante']].map(([key,symbol,title])=>`<div class="source-box"><div class="source-box-head"><strong>${symbol}</strong><h3>${title}</h3></div><textarea id="cmp-${key}" maxlength="50000" aria-label="${title}" placeholder="Pega sólo texto sintético…">${h(cmp[key])}</textarea></div>`).join('')}</div><div class="compare-controls"><label>Transformación<select id="cmp-stage">${options(Object.fromEntries(Object.entries(STAGES).map(([k,v])=>[k,v.label])),cmp.stage)}</select></label>${btn('compare-current','Usar fuente como H','doc')}${btn('compare-segment','Proponer segmentos','plus')}${btn('compare-add','Añadir unidad','edit')}${btn('compare-export','Exportar matriz','down')}</div><label class="check" style="max-width:890px"><input id="cmp-complete" type="checkbox" ${cmp.complete?'checked':''}>Declaro completas las fuentes y las unidades relevantes para esta tarea; revisé identidad, tiempo y equivalencia semántica. Sin esta adjudicación, L queda indeterminado.</label><div class="metric-row" id="cmp-metrics">${metricHTML(m)}</div><div class="judge-list">${rows.map((r,i)=>judgementHTML(r,i)).join('')||'<div class="empty"><h3>La ausencia se demuestra con una comparación.</h3><p>Carga entrega y registro. Propón segmentos o añade una unidad exacta. Revisa su significado antes de contarla como hecho.</p></div>'}</div><p class="semantic-note" id="cmp-status">${comparisonStatus(m)}</p><p class="semantic-note">L cuenta unidades no conservadas (omisión + contradicción + alteración). Las categorías son excluyentes; la pérdida de incertidumbre se informa además, sin volver a sumarla. Las unidades se deduplican por la clave semántica que declares, no por frases. Operacionalización manual de F(origen) ∖ F(destino), bajo la equivalencia semántica declarada; no es una métrica clínica validada.</p></section>`;}
function comparisonStatus(m){return m.nonConserved===null?'L no calculable todavía. Faltan adjudicaciones, una declaración de completitud o hay juicios incompatibles. Las omisiones revisadas se muestran aparte.':`L = ${m.nonConserved} unidades no conservadas: ${m.omitted} omitidas, ${m.contradictions} contradichas y ${m.altered} alteradas, entre ${m.units} unidades declaradas. Resultado de adjudicación manual, no de extracción automática ni de una referencia clínica independiente.`;}
function metricHTML(m){return [['L · '+STAGES[cmp.stage].symbol,m.nonConserved===null?'Indeterminado':String(m.nonConserved)],['Omisiones adjudicadas',m.omitted],['Contradicciones',m.contradictions],['Alteración de modalidad',m.altered],['Incertidumbre eliminada',m.uncertaintyLost],['Pendientes / no válidas',m.pending+m.invalid+m.conflicts]].map(([k,v])=>`<div class="metric"><strong ${String(v).length>9?'style="font-size:19px;padding:4px 0"':''}>${h(v)}</strong>${h(k)}</div>`).join('');}
function judgementHTML(r,i){return `<article class="judgement" data-row="${h(r.id)}"><div class="row-source"><small>UNIDAD ${i+1} · ${h(STAGES[r.stage].symbol)} · [${r.start}, ${r.end})</small>${h(r.source)}</div><label>Clave semántica<input data-field="key" value="${h(r.key)}" maxlength="500" placeholder="Sujeto / episodio / concepto / t"></label><label>Conservación<select data-field="status">${options(STATUS,r.status)}</select></label><label>Cita exacta en destino<textarea data-field="target" maxlength="3000" placeholder="Copia una cita de H o R…">${h(r.target)}</textarea></label><label>Incertidumbre<select data-field="uncertainty">${options(UNC,r.uncertainty)}</select></label><label>Fundamento<textarea data-field="note" maxlength="2000" placeholder="Explicita tiempo, polaridad y equivalencia…">${h(r.note)}</textarea></label>${btn('compare-remove','×','','plain',`data-row-id="${h(r.id)}" aria-label="Eliminar unidad ${i+1}"`)}</article>`;}
function newRow(source,start,stage=cmp.stage){return {id:'U-'+newId(),stage,start,end:start+source.length,source,key:'',target:'',status:'unassessed',uncertainty:'not_assessed',note:''};}
function safeMetrics(){const rows=cmp.rows.filter(r=>r.stage===cmp.stage).map(r=>{const targetText=cmp[STAGES[r.stage].to];if(r.target&&!targetText.includes(r.target))return {...r,note:''};return r;});return comparisonMetrics(rows,cmp.complete&&Boolean(cmp.task.trim()));}
function updateMetrics(){const m=safeMetrics();if($('#cmp-metrics'))$('#cmp-metrics').innerHTML=metricHTML(m);if($('#cmp-status'))$('#cmp-status').textContent=comparisonStatus(m);}
function seedComparison(){cmp.task='Caso SINT-01 · PICC A, episodio 1 · información explícita de la entrega de las 20:00';cmp.reference='08:00: PICC A presente.\n12:00: retiro de PICC A registrado a las 13:05.\n20:00: no hay una nueva observación del dispositivo.';cmp.handover='A las 12:00 se retiró PICC A.\nNo sé si la muestra fue enviada.\nEl paciente refiere dolor 6/10 en reposo.';cmp.record='A las 12:00 se retiró PICC A.\nLa muestra fue enviada.';cmp.stage='handover-record';const spans=textSpans(cmp.handover);cmp.rows=spans.map(s=>newRow(s.quote,s.start));Object.assign(cmp.rows[0],{key:'SINT-01 / PICC-A-1 / retiro / 12:00',status:'preserved',target:'A las 12:00 se retiró PICC A.',uncertainty:'not_applicable',note:'La misma acción realizada y el mismo tiempo están expresos en ambas fuentes.'});Object.assign(cmp.rows[1],{key:'SINT-01 / muestra-1 / envío / 20:00',status:'altered',target:'La muestra fue enviada.',uncertainty:'lost',note:'La falta explícita de conocimiento se transformó en afirmación categórica. Alteración epistémica, no contradicción factual adjudicada; no prueba que la muestra no fuera enviada.'});Object.assign(cmp.rows[2],{key:'SINT-01 / dolor-reposo / valor / 20:00',status:'omitted',uncertainty:'not_applicable',note:'El registro sintético completo no incluye el autorreporte ni su valor 6/10 en reposo.'});cmp.complete=true;state.compareDirty=true;render();toast('Ejemplo FALP diseñado y anotado manualmente; no es gold de Figshare.');}
function showDialog(title,body,foot='',wide=false){const d=$('#dialog');d.classList.toggle('wide',wide);d.innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${title}</h2>${btn('close-dialog','','close','plain','aria-label="Cerrar ventana"')}</div><div class="dialog-body">${body}<div class="error-box" id="dialog-error" role="alert"></div></div>${foot?`<div class="dialog-foot">${btn('close-dialog','Cancelar')}${foot}</div>`:''}`;d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();}
function dialogError(message){const e=$('#dialog-error');if(e){e.textContent=message;e.classList.add('show');e.scrollIntoView({block:'nearest'});}else toast(message);}
function closeDialog(){$('#dialog').close();}
function inputField(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${h(value??'')}" ${extra}></label>`;}
function newSourceDialog(){showDialog('Añadir una fuente sintética',`<p>La fuente queda intacta. Las reglas sólo proponen fragmentos y algunas modalidades en español. Ninguna fecha, observación ni raíz se inventa a partir de la fecha del archivo.</p><form id="source-form"><div class="form-grid">${inputField('Título','title','','text','required maxlength="200"') }<label>Canal<select name="channel">${options({record:'Registro escrito · R',handover:'Entrega comunicada · H',reference:'Perfil de referencia sintético · P'},'record')}</select></label>${inputField('Sujeto sintético · opcional','subject','','text','maxlength="200"')}${inputField('Autor / rol · opcional','author','','text','maxlength="200"')}${inputField('Documentado · UTC−03, opcional','authoredAt','','datetime-local')}${inputField('Disponible · UTC−03, opcional','availableAt','','datetime-local')}<label class="span2">Texto original<textarea name="text" rows="8" required maxlength="100000" placeholder="PICC A presente.\nSe indica retirar PICC A.\nPaciente refiere dolor 6/10 en reposo."></textarea></label><label class="check span2"><input type="checkbox" name="synthetic" required>Confirmo que son datos sintéticos. No ingresar información de pacientes reales.</label><label class="check span2"><input type="checkbox" name="newCase">Abrir como caso nuevo, separado del expediente actual.</label></div></form>`,btn('save-source','Extraer propuestas','plus','primary'));}
function reviewDialog(){const c=getSelected();if(!c||state.selected.startsWith('root:'))return;showDialog(`Revisar ${h(keyOf(c))}`,`<p>Se anexa una nueva versión. “Revisada” atesta una revisión documental: no confirma que la observación ocurrió ni que el estado clínico sea verdadero.</p><blockquote class="quote">${h(c.source.quote)}</blockquote><form id="review-form" data-id="${h(c.id)}" data-version="${c.version}"><div class="form-grid"><label>Modalidad<select name="modality">${options(MODALITIES,c.modality)}</select></label><label>Polaridad<select name="polarity">${options(POLARITIES,c.polarity)}</select></label>${inputField('Sujeto','subject',c.subject,'text','maxlength="1000"')}<label>A quién se refiere<select name="experiencer">${options({patient:'Paciente',relative:'Familiar',other:'Otro',unknown:'Desconocido'},c.experiencer)}</select></label>${inputField('Entidad','entity',c.entity,'text','maxlength="1000"')}${inputField('Episodio identificado','episode',c.episode,'text','maxlength="1000"')}${inputField('Atributo / concepto','concept',c.concept,'text','maxlength="1000"')}${inputField('Valor','value',c.value,'text','maxlength="1000"')}${inputField('Unidad explícita','unit',c.unit,'text','maxlength="1000"')}<label>Estado de captura<select name="capture">${options({present:'Presente',missing:'Faltante',ambiguous:'Ambiguo',not_applicable:'No aplica'},c.capture)}</select></label>${inputField('Tiempo afirmado · UTC−03','eventAt',toInput(c.eventAt),'datetime-local')}${inputField('Fin de intervalo · opcional','eventEnd',toInput(c.eventEnd),'datetime-local')}${inputField('Incertidumbre expresada · no confianza del extractor','uncertainty',c.uncertainty,'text','maxlength="1000"')}${inputField('Disponible nueva versión · UTC−03','availableAt',toInput(new Date().toISOString()),'datetime-local','required')}<label class="span2">Fundamento de la revisión<textarea name="reviewNote" required maxlength="2000">${h(c.reviewNote)}</textarea></label><label class="check span2"><input type="checkbox" name="unlinkRoots">Desvincular raíces de esta nueva versión. Necesario si cambio su contenido; no elimina versiones anteriores.</label></div></form>`,btn('save-review','Guardar nueva versión','check','primary'));}
function relationDialog(){if(currentView.claims.length<2){toast('Se necesitan dos afirmaciones visibles para relacionarlas.');return;}const list=Object.fromEntries(currentView.claims.map(c=>[keyOf(c),keyOf(c)+' · '+c.source.quote.slice(0,55)]));showDialog('Anotar una relación',`<p>La relación expresa una adjudicación documental con fundamento. “Deriva de” no asigna automáticamente una raíz ni demuestra dependencia causal.</p><form id="relation-form"><div class="form-grid"><label>Desde<select name="from">${options(list,state.selected)}</select></label><label>Hacia<select name="to">${options(list,Object.keys(list).find(x=>x!==state.selected))}</select></label><label>Tipo de relación<select name="type">${options({derives_from:'Deriva de',supports:'Apoya',contradicts:'Contradice · anotación',corrects:'Corrige',supersedes:'Sustituye'},'derives_from')}</select></label>${inputField('Disponible desde · UTC−03','availableAt',toInput(new Date().toISOString()),'datetime-local','required')}<label class="span2">Fuente y fundamento<textarea name="note" required maxlength="2000" placeholder="Indica la evidencia que permite establecer esta relación."></textarea></label></div></form>`,btn('save-relation','Añadir relación','link','primary'));}
function corpusDialog(){const items=state.corpus.length?state.corpus:CORPUS_SAMPLES;showDialog('Corpus de entregas sintéticas',`<div class="info-banner">Conway et al. (2026) estudian 203 entregas. Esta aplicación incluye <strong>3 diálogos completos seleccionados</strong> del archivo Figshare, sin anotaciones de consenso. Carga el archivo original para trabajar con todos sus casos.</div><div class="corpus-toolbar">${btn('load-corpus','Cargar corpus .md / .txt','up','primary')}<input id="corpus-search" type="search" placeholder="Buscar en el texto de los casos…" aria-label="Buscar corpus">${state.corpus.length?btn('corpus-reset','Volver a muestra'):''}</div><p id="corpus-count" style="margin:4px 0">${state.corpus.length?`${items.length} casos contados por separadores completos en ${h(state.corpusName)}. No se agrupan por nombre.`:'Muestra incluida: 3 casos. El recuento 103 del original procede de la auditoría aportada por Felipe; no de un recuento binario en esta entrega.'}</p><div class="corpus-items" id="corpus-items">${corpusItemsHTML(items)}</div><details><summary>Fuente, integridad y límites de uso</summary><ul class="audit-lines"><li>Figshare v1, DOI 10.6084/m9.figshare.32658084.v1. Aaron Conway; licencia CC BY 4.0.</li><li>La API oficial enumera un único archivo: tpch_text_values.md, 184.927 bytes. No lista anotaciones ni código aparte.</li><li>Los tres diálogos se copiaron del texto recuperado por Firecrawl, sin traducción. No se verificó una copia binaria completa ni su hash.</li><li>NICTA/CSIRO no está incluido. Sus perfiles y registros pueden cargarse para comparación local cuando dispongas de acceso autorizado.</li><li>Un nombre repetido no acredita identidad de paciente, episodio ni orden temporal. Cada caso se abre separado.</li><li>Las frases sobre tratamientos pertenecen a escenarios sintéticos y no se ofrecen como recomendaciones clínicas.</li></ul><p>${h(FIGSHARE_META.attribution)}</p></details>`, '',true);}
function corpusItemsHTML(items,needle=''){return items.map((x,i)=>({x,i})).filter(({x})=>(x.title+' '+x.text).toLowerCase().includes(needle.toLowerCase())).slice(0,300).map(({x,i})=>`<div class="corpus-item"><div><strong>${h(x.id)} · ${h(x.title||'Entrega sintética '+x.index)}</strong><small>${x.text.length.toLocaleString('es-CL')} caracteres · ${uncertaintyCues(x.text).length} indicadores léxicos candidatos · sin fecha inferida</small><p>${h(x.text.slice(0,170))}</p></div>${btn('open-corpus','Abrir','','',`data-index="${i}"`)}</div>`).join('')||'<div class="empty">Sin coincidencias.</div>';}
function exportDialog(){showDialog('Exportar trabajo',`<p>Los textos y las anotaciones viven sólo en esta sesión. Exporta antes de cerrar o cambiar de caso. La vista respeta κ; el expediente completo incluye todo su historial, también información posterior al corte.</p><div class="export-grid">${btn('download-bundle','Expediente completo · JSON<small>Fuentes, versiones, raíces y relaciones. Reimportable. No confundir con vista al corte.</small>','down','export-option')}${btn('download-report','Vista documental · Markdown<small>Sólo información disponible en el corte actual, con fuentes y advertencias.</small>','doc','export-option')}${btn('download-png','Grafo local · PNG<small>Captura del lienzo Canvas 2D, tal como está visible.</small>','graph','export-option')}${btn('download-svg','Grafo documental · SVG<small>Vista documental al corte con distribución de lectura, independiente del grafo local.</small>','graph','export-option')}${btn('compare-export','Matriz de comparación · JSON<small>Perfil, entrega, registro y adjudicaciones manuales. Separada del expediente.</small>','compare','export-option')}</div>`);}
function aboutDialog(){showDialog('Teoría convertida en una herramienta',`<h3>D<sub>t|κ</sub><sup>(a,q)</sup> = View<sub>a,q,t</sub>(G<sub>κ</sub>)</h3><p>Fuente: <em>Hacia una teoría del estado documental clínico</em>, Método FALP, compilación LaTeX v0.3, 13 de octubre de 2026. Secciones 3, 5, 6, 7.2, 8.1, 9.1, 11, 15 y 33.</p><div class="info-banner">S (situación clínica), O (evidencia/observaciones), H (información comunicada) y R (registro) son objetos distintos. La aplicación representa afirmaciones documentadas; no conoce S ni la comprensión de una persona.</div><h3>Qué hace este prototipo</h3><p>Conserva fragmentos exactos, modalidades, polaridad, tiempos y procedencia. Muestra candidatos de incompatibilidad y permite anotar relaciones/versiones. El actor se registra como contexto explícito; no cambia privilegios ni personaliza automáticamente la interpretación. La tarea aplica un filtro transparente de conceptos o modalidades.</p><h3>Qué no demuestra</h3><p>No es NLP clínico validado, no identifica copias por similitud, no resuelve automáticamente identidad/episodio ni crea hechos omitidos. Una revisión humana aquí es una atestación documental sin identidad autenticada. Las pruebas de Lean y Wolfram del manuscrito no certifican este código nuevo.</p><h3>Privacidad y persistencia</h3><p>No hay servidor de datos, analítica, API de modelos, almacenamiento local persistente ni sincronización. ${graphBuildMode()==='offline'?'El visor Canvas 2D está integrado: no descarga G6, Quartz, D3 ni PixiJS.':'El visor requiere recursos externos.'} Todo se pierde al cerrar salvo lo exportado. Esta arquitectura no sustituye una evaluación institucional de seguridad. Sólo datos sintéticos.</p><h3>Corpus</h3><p>Conway et al. JMIR Nursing 2026;9:e106133. DOI 10.2196/106133. Tres diálogos seleccionados, CC BY 4.0. Las anotaciones de esta app no son las del estudio. No hay resultados de desempeño sobre los 203 casos.</p>`);}
function addUnitDialog(){const stage=STAGES[cmp.stage],text=cmp[stage.from];if(!text.trim()){toast('Primero ingresa la fuente de esta transformación.');return;}showDialog('Añadir una unidad para adjudicar',`<p>Selecciona una cita exacta de ${h(stage.from==='reference'?'P':'H')}. Puede contener más de un concepto: crea unidades distintas con claves semánticas distintas, en lugar de asumir que una frase es un hecho.</p><form id="unit-form"><label>Cita exacta<textarea name="quote" required maxlength="3000"></textarea></label><label style="margin-top:13px">Offset de inicio · opcional si la cita aparece una sola vez<input name="start" type="number" min="0" step="1"></label></form>`,btn('save-unit','Añadir pendiente','plus','primary'));}
function download(text,name,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Archivo preparado: '+name);}
function safeName(s){return String(s).replace(/[^A-Za-z0-9_-]/g,'_').slice(0,80)||'caso';}
function formData(selector){const f=$(selector);if(!f.reportValidity())return null;return {form:f,data:new FormData(f)};}
function saveSource(){const x=formData('#source-form');if(!x)return;const f=x.data,newCase=f.has('newCase');if(newCase&&!canReplace())return;const b=newCase?emptyBundle():structuredClone(state.bundle);if(newCase)b.case={id:'SINT-'+Date.now(),title:f.get('title').trim(),synthetic:true};const id='D-'+newId().slice(0,8),d={id,title:f.get('title').trim(),text:f.get('text'),subject:f.get('subject').trim()||null,author:f.get('author').trim()||null,channel:f.get('channel'),authoredAt:fromInput(f.get('authoredAt')),availableAt:fromInput(f.get('availableAt'))};if(!d.text.trim())throw Error('El texto no puede estar vacío.');b.documents.push(d);const cs=d.channel==='handover'?dialogueClaims(d):extractClaims(d);b.claims.push(...cs);const check=validateBundle(b);if(!check.ok)throw Error(check.errors.join('\n'));state.bundle=b;state.context.task='all';state.context.kappa=null;state.context.clinicalAt=null;state.source=id;state.selected=cs[0]?keyOf(cs[0]):null;state.tab='graph';state.mobile='text';state.dirty=true;resetGraph();state.graphDrawer='source';closeDialog();render();toast(`${cs.length} propuestas. Tiempos y raíces no documentados siguen desconocidos.`);}
function saveReview(){const x=formData('#review-form');if(!x)return;const d=x.data,patch={};for(const k of ['subject','entity','episode','concept','value','unit','uncertainty'])patch[k]=String(d.get(k)).trim()||null;for(const k of ['experiencer','modality','polarity','capture'])patch[k]=d.get(k);patch.eventAt=fromInput(d.get('eventAt'));patch.eventEnd=fromInput(d.get('eventEnd'));patch.review='reviewed';patch.reviewNote=d.get('reviewNote').trim();if(d.has('unlinkRoots'))patch.rootIds=[];const id=x.form.dataset.id;state.bundle=addRevision(state.bundle,id,+x.form.dataset.version,patch,fromInput(d.get('availableAt')));state.dirty=true;state.selected=id+'@'+(+x.form.dataset.version+1);state.context.kappa=null;resetGraph();closeDialog();render();toast('Nueva versión añadida. Se abrió el archivo; los cortes anteriores se conservan.');}
function saveRelation(){const x=formData('#relation-form');if(!x)return;const d=x.data,b=structuredClone(state.bundle);b.relations.push({id:'L-'+newId().slice(0,8),from:d.get('from'),to:d.get('to'),type:d.get('type'),availableAt:fromInput(d.get('availableAt')),note:d.get('note').trim()});const check=validateBundle(b);if(!check.ok)throw Error(check.errors.join('\n'));state.bundle=b;state.context.kappa=null;state.dirty=true;closeDialog();render();toast('Relación anotada; no asigna raíces ni confirma hechos clínicos.');}
const ACTIONS={
  'tab':el=>{state.tab=el.dataset.tab;render();},'mobile':el=>{state.mobile=el.dataset.panel;render();},'detail':()=>showGraphDrawer('detail'),'graph-close':()=>showGraphDrawer('closed'),
  'time':el=>{state.context.kappa=demoTime(el.dataset.time);state.context.clinicalAt=demoTime(el.dataset.time);resetGraph();render();},
  'demo':()=>{if(canReplace())adopt(demoBundle());},'new-source':newSourceDialog,'review':reviewDialog,'relation':relationDialog,'corpus':corpusDialog,'about':aboutDialog,'export':exportDialog,
  'close-dialog':closeDialog,'save-source':saveSource,'save-review':saveReview,'save-relation':saveRelation,
  'select-root':el=>selectNode('root:'+el.dataset.root),'table-node':el=>{state.tab='graph';state.graphDrawer='detail';selectNode(el.dataset.key);},
  'issue':()=>{if(currentView.issues[0]){selectNode(currentView.issues[0].to);showGraphDrawer('detail');}},
  'import':()=>$('#bundle-file').click(),'load-corpus':()=>$('#corpus-file').click(),
  'corpus-reset':()=>{state.corpus=[];state.corpusName='';corpusDialog();},
  'open-corpus':el=>{if(!canReplace())return;const external=state.corpus.length>0,item=(external?state.corpus:CORPUS_SAMPLES)[+el.dataset.index];if(!item)throw Error('Caso no encontrado.');const meta=external?{title:'Entrega '+item.id+' · corpus local',dataset:state.corpusName,synthetic:true,license:'No verificada por la aplicación',retrieval:'Importación local por el usuario; no se atribuye al estudio automáticamente'}:{...FIGSHARE_META,title:item.title};adopt(corpusBundle(item,meta),{archive:true});closeDialog();toast('Caso separado, sin fechas ni identidad de trayectoria inferidas.');},
  'download-bundle':()=>{download(JSON.stringify(state.bundle,null,2),'TRAZA-'+safeName(state.bundle.case.id)+'.json','application/json');state.dirty=false;},
  'download-report':()=>download(markdownReport(state.bundle,currentView,state.context),'TRAZA-vista.md','text/markdown'),
  'download-svg':()=>{if(!currentView.claims.length)throw Error('No hay afirmaciones para exportar.');download(makeGraph(currentView,state.selected).exported,'TRAZA-grafo-lectura-completo.svg','image/svg+xml');},
  'download-png':async()=>{if(!graphPanel)throw Error('Abre primero la vista Grafo.');const url=await graphPanel.png();if(typeof url!=='string'||!url.startsWith('data:image/png'))throw Error('El visor no devolvió un PNG válido.');const a=document.createElement('a');a.href=url;a.download='TRAZA-grafo-local.png';a.click();},
  'compare-demo':()=>{if(cmp.rows.length&&!window.confirm('¿Reemplazar la comparación por el ejemplo anotado?'))return;seedComparison();},
  'compare-current':()=>{const d=currentView.documents.find(x=>x.id===state.source);if(!d)throw Error('Selecciona primero una fuente en el grafo.');if(cmp.rows.length&&!window.confirm('Al cambiar H se invalidarán las adjudicaciones. ¿Continuar?'))return;cmp.handover=d.text;cmp.rows=[];cmp.complete=false;state.compareDirty=true;render();toast('Fuente copiada como H para comparación local; no es un registro resultante.');},
  'compare-segment':()=>{const t=cmp[STAGES[cmp.stage].from];if(!t.trim())throw Error('Falta la fuente de origen para esta transformación.');if(cmp.rows.some(r=>r.stage===cmp.stage)&&!window.confirm('¿Reemplazar las unidades de esta transformación por propuestas sin evaluar?'))return;const spans=textSpans(t);if(spans.length>120)throw Error('Máximo 120 segmentos por comparación; reduce el alcance.');cmp.rows=cmp.rows.filter(r=>r.stage!==cmp.stage).concat(spans.map(s=>newRow(s.quote,s.start)));cmp.complete=false;state.compareDirty=true;render();},
  'compare-add':addUnitDialog,'save-unit':()=>{const x=formData('#unit-form');if(!x)return;const quote=x.data.get('quote');if(!quote.trim())throw Error('La cita no puede ser vacía.');const text=cmp[STAGES[cmp.stage].from],input=x.data.get('start');let start=input===''?text.indexOf(quote):Number(input);if(start<0||text.slice(start,start+quote.length)!==quote)throw Error('La cita no coincide exactamente con la fuente y ese offset.');if(input===''&&text.indexOf(quote,start+1)!==-1)throw Error('La cita aparece más de una vez. Declara el offset exacto de inicio.');if(cmp.rows.length>=240)throw Error('Máximo 240 unidades en la matriz.');cmp.rows.push(newRow(quote,start));cmp.complete=false;state.compareDirty=true;closeDialog();render();},
  'compare-remove':el=>{cmp.rows=cmp.rows.filter(r=>r.id!==el.dataset.rowId);cmp.complete=false;state.compareDirty=true;render();},
  'compare-export':()=>{validateComparisonFile(cmp);download(JSON.stringify({...cmp,metrics:{...safeMetrics(),stage:cmp.stage},limitations:'Adjudicación manual; no gold del estudio, no NLP validado. P no equivale a S. nonConserved = omisiones + contradicciones + alteraciones en claves semánticas declaradas. loss conserva el conteo específico de omisiones por compatibilidad; no es L general.'},null,2),'TRAZA-matriz.json','application/json');state.compareDirty=false;}
};
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const fn=ACTIONS[button.dataset.action];if(fn)try{await fn(button);}catch(err){if($('#dialog').open)dialogError(err.message);else toast(err.message);}});
document.addEventListener('change',e=>{const el=e.target,id=el.id;try{
  if(['actor','task','clinical-at','cutoff','archive','history'].includes(id)){
    if(id==='actor')state.context.actor=el.value;
    if(id==='task')state.context.task=el.value;
    if(id==='clinical-at')state.context.clinicalAt=fromInput(el.value);
    if(id==='cutoff')state.context.kappa=fromInput(el.value);
    if(id==='archive')state.context.kappa=el.checked?null:state.context.clinicalAt||demoTime('20:05');
    if(id==='history')state.context.includeHistory=el.checked;
    resetGraph();render();
  }else if(id==='source-select'){state.source=el.value;const c=currentView.claims.find(c=>c.source.documentId===el.value);state.selected=c?keyOf(c):null;render();}
  else if(id==='claim-search'){state.search=el.value;render();$('#claim-search').focus();}
  else if(['hmm-step','hmm-late','hmm-new'].includes(id)){if(id==='hmm-step')state.labStep=+el.value;else if(id==='hmm-late')state.labLate=el.checked;else state.labNew=el.checked;const top=$('.scroll-page').scrollTop;render();$('.scroll-page').scrollTop=top;}
  else if(id.startsWith('cmp-')){
    if(id==='cmp-stage'){cmp.stage=el.value;cmp.complete=false;render();}
    else if(id==='cmp-complete'){cmp.complete=el.checked;state.compareDirty=true;updateMetrics();}
    else if(['cmp-reference','cmp-handover','cmp-record','cmp-task'].includes(id)){const k=id.slice(4);if(cmp[k]!==el.value){cmp[k]=el.value;cmp.rows=[];cmp.complete=false;state.compareDirty=true;const top=$('.scroll-page').scrollTop;render();$('.scroll-page').scrollTop=top;toast('Fuentes o tarea modificadas: adjudicaciones anteriores invalidadas.');}}
  }else if(el.dataset.field){const r=cmp.rows.find(r=>r.id===el.closest('[data-row]')?.dataset.row);if(!r)return;r[el.dataset.field]=el.value;state.compareDirty=true;if(el.dataset.field==='target'&&r.target&&!cmp[STAGES[r.stage].to].includes(r.target)){el.setAttribute('aria-invalid','true');toast('La cita destino no coincide exactamente con su fuente; L queda bloqueado.');}else el.removeAttribute('aria-invalid');updateMetrics();}
}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='copy-range'){state.labCopies=+el.value;$('#copy-count').textContent=el.value;const p=copyPosterior(state.labCopies,true);$('#copy-naive').textContent=p.toFixed(6);$('#naive-bar').style.width=p*100+'%';}if(el.id==='corpus-search')$('#corpus-items').innerHTML=corpusItemsHTML(state.corpus.length?state.corpus:CORPUS_SAMPLES,el.value);});
function validateComparisonFile(c){if(!c||c.schema!=='traza-comparison/0.1'||c.synthetic!==true)throw Error('Matriz sintética no compatible.');for(const f of ['task','reference','handover','record'])if(typeof c[f]!=='string'||c[f].length>50000)throw Error('Fuente de matriz inválida.');if(!Object.hasOwn(STAGES,c.stage)||!Array.isArray(c.rows)||c.rows.length>240||typeof c.complete!=='boolean')throw Error('Estructura de matriz no válida.');for(const r of c.rows){if(!Object.hasOwn(STAGES,r.stage)||typeof r.id!=='string'||typeof r.source!=='string'||!r.source.trim()||!Number.isInteger(r.start)||r.start<0||r.end!==r.start+r.source.length||c[STAGES[r.stage].from].slice(r.start,r.end)!==r.source)throw Error('Una unidad perdió su cita de origen.');for(const f of ['key','target','note'])if(typeof r[f]!=='string'||r[f].length>3000)throw Error('Campo de adjudicación inválido.');if(!Object.hasOwn(UNC,r.uncertainty)||!Object.hasOwn(STATUS,r.status))throw Error('Estado no compatible.');if(r.target&&!c[STAGES[r.stage].to].includes(r.target))throw Error('Una cita de destino no coincide con el texto. Corrígela antes de exportar.');}return true;}
$('#bundle-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>4000000)throw Error('Máximo 4 MB por expediente.');const text=await file.text(),obj=JSON.parse(text,(k,v)=>{if(['__proto__','constructor','prototype'].includes(k))throw Error('Clave JSON no permitida.');return v;});if(obj.schema==='traza-comparison/0.1'){validateComparisonFile(obj);if(cmp.rows.length&&!window.confirm('¿Reemplazar la matriz de comparación actual?'))return;for(const k of Object.keys(cmp))cmp[k]=structuredClone(obj[k]);state.tab='compare';render();toast('Matriz reimportada con sus fuentes y adjudicaciones.');}else{const b=parseBundle(text);if(!canReplace())return;adopt(b,{archive:true});toast('Expediente reimportado. Modo archivo para no inventar un corte.');}}catch(err){toast('No se importó: '+err.message);}});
$('#corpus-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>4000000)throw Error('Máximo 4 MB de texto.');const items=splitCorpus(await file.text());if(!items.length)throw Error('Archivo sin casos.');if(!window.confirm(`Se detectaron ${items.length} casos. ¿Confirmas que el archivo contiene exclusivamente datos sintéticos y que tienes permiso para usarlo?`))return;state.corpus=items;state.corpusName=file.name;corpusDialog();}catch(err){dialogError(err.message);}});

window.addEventListener('beforeunload',e=>{if(state.dirty||state.compareDirty){e.preventDefault();e.returnValue='';}});
render();
